import {state} from '../../core/state.js?v=5b47e3c89a10';
import {sourceQuery} from '../../core/annotation-scope.js?v=5b47e3c89a10';
import {esc,panel,btn} from '../../core/ui.js?v=5b47e3c89a10';
export function administration(data,runId){const manage=state.workspace.project.can_manage;return (manage?panel('Thích ứng từ phản hồi đã duyệt',`<p>${esc(data.readiness.message)}</p><p>${Object.entries(data.readiness.counts).map(([k,n])=>esc(k)+': '+n).join(' · ')} · ${data.readiness.sources} nguồn. Thiếu lớp: ${esc(data.readiness.missing_classes.join(', ')||'không')}.</p>${btn('Chụp dataset theo nguồn','collaboration:dataset')}${data.datasets.map(d=>`<div class="review-run">Dataset #${d.id} · ${esc(JSON.stringify(d.counts))} ${btn('Train ứng viên','collaboration:train','sm','',`data-id="${d.id}"`)}</div>`).join('')}<p>Chọn siêu tham số và xem ứng viên bằng validation; test chỉ báo cáo theo protocol. Không tự kích hoạt model mới.</p>${data.models.map(m=>`<div class="review-run"><b>${esc(m.name)}</b> · ${esc(m.compatibility.state)}<p>${esc(m.compatibility.reason)}</p>${m.validation?`<p>Validation macro-F1: ${Number(m.validation.macro_f1).toFixed(4)}</p>`:''}${m.incumbent_validation?`<p>Model đang chạy trên cùng validation: ${Number(m.incumbent_validation.macro_f1).toFixed(4)}</p>`:''}${btn('Kích hoạt / rollback','collaboration:activate','sm','',`data-id="${m.id}" ${m.compatibility.state==='compatible'?'':'disabled'}`)}</div>`).join('')}<p>Few-shot retrieval chỉ dùng phản hồi con người đã được quản lý duyệt; không cập nhật trọng số API.</p>`):'')+
 panel('Điều khiển và báo cáo',`${btn('Retry local lỗi','collaboration:retry','','', 'data-branch="local"')}${btn('Retry API lỗi','collaboration:retry','','','data-branch="api"')}${btn('Xuất so sánh theo ID','collaboration:report')}${manage?`<a class="btn" href="/api/studio/export?project=${state.workspace.project.id}&format=csv_sentence&scope=human${sourceQuery()}">Xuất nhãn con người (CSV)</a>`:''}<p>Retry giữ kết quả thành công. Khi cấu hình đã thay đổi, tạo lượt mới. Báo cáo chỉ so cùng schema và cùng ID/hash văn bản.</p>`)+
 panel('Lịch sử schema',data.schemas.map(s=>`<details><summary>v${s.version} · ${esc(s.sha256.slice(0,12))}</summary><pre>${esc(JSON.stringify(s.snapshot,null,2))}</pre></details>`).join(''));
}
